uniform float uTime; // Elapsed time in seconds.

void main() {
    float phase = fract(uTime);
    float brightness = 0.5 - 0.5 * cos(6.28318530718 * phase);
    gl_FragColor = vec4(vec3(brightness), 1.0);
}
```

